build("03_rastreamento_e_contagem_de_passagens", [
 ("md", "# 03 · Rastreamento e contagem de passagens\nTodos os números vêm de `experiments/tracking_eval.json` (gerado por `training/eval_tracking.py`). Parâmetros do tracker **não ajustados** nestes vídeos."),
 ("md", "## A · Vídeo aéreo SINTÉTICO (janela deslizando sobre foto real, GT exato)\n⚠ Câmera simulada, animais estáticos: valida a cadeia, **não** o comportamento real de bovinos em vídeo aéreo."),
 ("code", SETUP + "\nA = R['A_sintetico']\ndf = pd.DataFrame([{'método': k, 'HOTA': m['HOTA'], 'IDF1': m['IDF1'], 'IDF1@0,3': m['IDF1_iou0.3'], 'trocas ID': m['IDSW'], 'IDs previstos': m['n_pred_ids'], 'passagens': m['passagens_linha_x640']['total_passagens']} for k, m in A['metodos'].items()])\nprint('GT:', A['gt_ids'], 'animais;', 'passagens GT na linha x=640:', A['passagens_GT_linha_x640']['total_passagens'])\ndf.round(3)"),
 ("code", "o = pd.DataFrame([{'método': k, 'HOTA': m['HOTA'], 'IDF1': m['IDF1'], 'trocas ID': m['IDSW'], 'IDs previstos': m['n_pred_ids']} for k, m in A['metodos_com_deteccao_perfeita'].items()])\nprint('COM DETECÇÕES PERFEITAS (isola o rastreador do detector):'); print(o.round(3).to_string(index=False))\nprint('\\ndetector real: %.1f detecções/quadro vs %.1f animais reais/quadro' % (A['deteccao_isolada']['deteccoes_por_quadro_media'], A['deteccao_isolada']['gt_visiveis_por_quadro_media']))"),
 ("md", "**Leitura.** Com detecções perfeitas o ByteTrack próprio é quase perfeito (IDF1 ≈ 1). Com as detecções reais o desempenho cai muito: o gargalo é o **detector** (revocação baixa, caixas frouxas), não a associação. Nesta cena fácil e suave, o baseline IoU também é perfeito com detecção perfeita; a vantagem do ByteTrack aparece com detecções ruidosas (cenário B)."),
 ("md", "## Trajetórias: GT × rastreador (detecções reais)"),
 ("code", "import cv2\nfrom cattlecount.tracking import ByteTracker, TrackerConfig\nz = np.load('../runs/tracking/synthetic_pan_full.npz', allow_pickle=True)['d']\ngt = np.loadtxt('../sample_data/demo_pan_synthetic_gt.txt', delimiter=',')\ntr = ByteTracker(TrackerConfig(high_thresh=.25, low_thresh=.1, new_track_thresh=.35))\nout = {k: tr.update(d) for k, d in enumerate(z, 1)}\nfig, ax = plt.subplots(1, 2, figsize=(11, 3.6), sharey=True)\nfor g in sorted(set(gt[:, 1])):\n    r = gt[gt[:, 1] == g]; ax[0].plot(r[:, 0], r[:, 2] + r[:, 4] / 2, lw=1.5)\nax[0].set_title('GT: x do centro de cada animal (câmera se move)'); ax[0].set_xlabel('quadro'); ax[0].set_ylabel('x (px)')\nids = sorted({int(r[4]) for rr in out.values() for r in rr})\nfor i in ids:\n    pts = [(k, (r[0] + r[2]) / 2) for k, rr in out.items() for r in rr if int(r[4]) == i]\n    ax[1].plot(*zip(*pts), lw=1.5)\nax[1].axhline(640, color='k', ls='--', lw=.8); ax[0].axhline(640, color='k', ls='--', lw=.8)\nax[1].set_title('ByteTrack: x do centro por ID (%d IDs)' % len(ids)); ax[1].set_xlabel('quadro'); plt.tight_layout(); plt.show()"),
 ("md", "## B · Vídeo terrestre real (Mendeley; GT de um clipe, viciado em detector COCO)"),
 ("code", "B = R['B_terrestre_mendeley']\nprint(B['aviso']); print('quadros:', B['n_frames'], '| animais no GT:', B['gt_ids'])\npd.DataFrame([{'método': k, 'HOTA': m['HOTA'], 'IDF1': m['IDF1'], 'MOTA': m['MOTA'], 'trocas ID': m['IDSW'], 'IDs previstos': m['n_pred_ids']} for k, m in B['metodos'].items()]).round(3)"),
 ("md", "**Leitura.** O ByteTrack próprio e o do Ultralytics (mesmas detecções, mesmos limiares) dão resultados praticamente iguais, o que valida a implementação própria; ambos superam o baseline IoU, que fragmenta muito (mais IDs e mais trocas). Atenção: o GT favorece detectores tipo COCO e o cenário é terrestre."),
])
